select 'SAT_AGREEMENT_COMMERCIAL_TERMS' satellite,'HUB_AGREEMENT' parent_table,count_if(s.AGREEMENT_HKEY is null or p.k is null) orphan_or_null_rows from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AGREEMENT_COMMERCIAL_TERMS s left join (select distinct AGREEMENT_HKEY k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_AGREEMENT) p on p.k=s.AGREEMENT_HKEY where startswith(s.RECORD_SOURCE, 'OPUS_') and (s.AGREEMENT_HKEY is null or s.AGREEMENT_HKEY <> TO_BINARY(REPEAT('0', 32), 'HEX'))
